// orders four consecutive events per thread, then threads by lane/warp/block.
// scratch[0:8] is one entry per warp; scratch[8] stores the block total.
__device__ __forceinline__ int post_event_prefix(int value,int* scratch,int& total){
 const int lane=libero_warp::lane(),wid=libero_warp::warp(),nw=int(blockDim.x)>>5;
 const int rank=libero_warp::exclusive_sum(value),sum=libero_warp::sum(value);
 if(lane==0)scratch[wid]=sum;
 __syncthreads();
 if(wid==0){
  const int own=lane<nw?scratch[lane]:0;
  const int prefix=libero_warp::exclusive_sum(own),all=libero_warp::sum(own);
  if(lane<nw)scratch[lane]=prefix;
  if(lane==0)scratch[8]=all;
 }
 __syncthreads();
 const int result=scratch[wid]+rank;total=scratch[8];
 // Every warp must read its prefix before a later tile reuses the scratch.
 __syncthreads();
 return result;
}

// Stable body-key counting/radix distribution. Integer histogram atomics only
// establish counts: scatter positions come from deterministic prefixes, never
// from an atomic arrival order. Each bit needs one event pass; the existing
// body histogram supplies its global zero count without an extra event scan.
// Work O(n*ceil(log2(b+1))+b*ceil(log2(b+1))); storage 4*cc private int32.
__device__ inline void post_contact_index_radix(int n,int cc,int b,const int* adr,
 const int* g1,const int* g2,const int* gb,int* index,int* offsets,int* counts,
 int* ping,int* pong,int* body_keys=nullptr){
 __shared__ int prefix_scratch[9];
 __shared__ int zero_count;
 for(int body=threadIdx.x;body<b;body+=blockDim.x)counts[body]=0;
 __syncthreads();
 const int events=2*n;
 for(int event=threadIdx.x;event<events;event+=blockDim.x){
  ping[event]=event;
  const int body=post_event_body(event,b,adr,g1,g2,gb);
  if(body_keys)body_keys[event]=body;
  if(body<b)atomicAdd(counts+body,1);
 }
 __syncthreads();
 if(threadIdx.x==0){
  int total=0;offsets[0]=0;
  for(int body=1;body<b;body++){offsets[body]=total;total+=counts[body];}
  offsets[b]=total;
 }
 __syncthreads();
 int* src=ping;int* dst=pong;
 // sentinel body b requires floor(log2(b))+1 bits, also for a power-of-two b.
 for(unsigned bit=1;bit<=unsigned(b);bit<<=1){
  if(threadIdx.x==0){
   int total=0;
   for(int body=1;body<b;body++)if((unsigned(body)&bit)==0)total+=counts[body];
   if((unsigned(b)&bit)==0)total+=events-offsets[b];
   zero_count=total;
  }
  __syncthreads();
  const int zeros=zero_count;
  int consumed_zeros=0;
  // Four events per thread amortize synchronization across 128--1024 events.
  for(int base=0;base<events;base+=4*int(blockDim.x)){
   int values[4],zero[4],own=0;
   #pragma unroll
   for(int r=0;r<4;r++){
    const int i=base+4*int(threadIdx.x)+r;
    values[r]=i<events?src[i]:0;
    zero[r]=i<events&&((unsigned(body_keys?body_keys[values[r]]:post_event_body(values[r],b,adr,g1,g2,gb))&bit)==0);
    own+=zero[r];
   }
   int tile_zeros=0;
   const int zero_rank=post_event_prefix(own,prefix_scratch,tile_zeros);
   int local_zero=0,local_one=0;
   #pragma unroll
   for(int r=0;r<4;r++){
    const int i=base+4*int(threadIdx.x)+r;
    if(i<events){
     const int destination=zero[r]?consumed_zeros+zero_rank+local_zero++:
      zeros+base-consumed_zeros+4*int(threadIdx.x)-zero_rank+local_one++;
     dst[destination]=values[r];
    }
   }
   consumed_zeros+=tile_zeros;
  }
  __syncthreads();
  int* next=src;src=dst;dst=next;
 }
 // Only the valid prefix is defined. Preserve the caller's held index tail.
 for(int i=threadIdx.x;i<offsets[b];i+=blockDim.x)index[i]=src[i];
 __syncthreads();
}

// Stable 2/3-bit LSD distribution. Every bucket rank is a deterministic
// block prefix followed by the four events in source order. Atomics supply
// histogram counts only. Current keys remain indexed by ORIGINAL event ID.
// A bucket-prefix pass reuses nine shared ints; no atomic scatter positions.
__device__ inline void post_contact_index_multibit(int n,int cc,int b,const int* adr,
 const int* g1,const int* g2,const int* gb,int* index,int* offsets,int* counts,
 int* ping,int* pong,int* keys){
 constexpr int buckets=1<<LIBERO_POST_RADIX_BITS;
 __shared__ int prefix_scratch[9], bucket_start[buckets];
 for(int body=threadIdx.x;body<b;body+=blockDim.x)counts[body]=0;
 __syncthreads();
 const int events=2*n;
 for(int event=threadIdx.x;event<events;event+=blockDim.x){
  ping[event]=event;const int body=post_event_body(event,b,adr,g1,g2,gb);
  if(keys)keys[event]=body;
  if(body<b)atomicAdd(counts+body,1);
 }
 __syncthreads();
 if(threadIdx.x==0){int total=0;offsets[0]=0;
  for(int body=1;body<b;body++){offsets[body]=total;total+=counts[body];}
  offsets[b]=total;
 }
 __syncthreads();
 int* src=ping;int* dst=pong;
 for(unsigned shift=0;shift<32&&(unsigned(b)>>shift)!=0;shift+=LIBERO_POST_RADIX_BITS){
  if(threadIdx.x==0){int total=0;
   for(int bucket=0;bucket<buckets;bucket++){
    bucket_start[bucket]=total;
    for(int body=1;body<b;body++)if(((unsigned(body)>>shift)&(buckets-1))==unsigned(bucket))total+=counts[body];
    if(((unsigned(b)>>shift)&(buckets-1))==unsigned(bucket))total+=events-offsets[b];
   }
  }
  __syncthreads();
  int consumed[buckets]={0};
  for(int base=0;base<events;base+=4*int(blockDim.x)){
   int value[4],digit[4];
   #pragma unroll
   for(int r=0;r<4;r++){
    const int i=base+4*int(threadIdx.x)+r;value[r]=i<events?src[i]:0;
    digit[r]=i<events?int((unsigned(keys?keys[value[r]]:post_event_body(value[r],b,adr,g1,g2,gb))>>shift)&(buckets-1)):-1;
   }
   #pragma unroll
   for(int bucket=0;bucket<buckets;bucket++){
    int own=0;for(int r=0;r<4;r++)own+=int(digit[r]==bucket);
    int tile_count=0;const int rank=post_event_prefix(own,prefix_scratch,tile_count);
    int local=0;
    #pragma unroll
    for(int r=0;r<4;r++)if(digit[r]==bucket)
     dst[bucket_start[bucket]+consumed[bucket]+rank+local++]=value[r];
    consumed[bucket]+=tile_count;
   }
  }
  __syncthreads();int* next=src;src=dst;dst=next;
 }
 for(int i=threadIdx.x;i<offsets[b];i+=blockDim.x)index[i]=src[i];
 __syncthreads();
}

// mode 0 chooses a conservative workload heuristic, 1 forces the scan, 2
// forces radix. The heuristic is configurable and is not a measured winner.
__device__ __noinline__ void post_contact_index(int n,int cc,int b,const int* adr,
 const int* g1,const int* g2,const int* gb,int* index,int* offsets,int* counts,
 int* ping=nullptr,int* pong=nullptr,int mode=0,int radix_min_contacts=256,
 int* cached_body=nullptr,int* cached_meta=nullptr,int topology_cache=0){
 const bool cache=topology_cache!=0&&cached_body&&cached_meta;
 // An exact event/body key is sufficient: CSR stores event j/side, and RNE
 // always reads current force/address/frame/position values for that event.
 // No floating identity, hash collision, stale ncon, or geom-array epoch guess.
 if(cache&&cached_meta[0]==1&&cached_meta[1]==n){
  bool different=false;
  for(int event=threadIdx.x;event<2*n;event+=blockDim.x)
   different|=cached_body[event]!=post_event_body(event,b,adr,g1,g2,gb);
  if(!__syncthreads_or(different))return;
 }
 const bool radix=ping&&pong&&(mode==2||(mode==0&&b>=32&&n>=radix_min_contacts));
 // Compare the entire old key before invalidating or overwriting any entry.
 if(LIBERO_POST_ONCE_KEYS){
  if(cached_meta&&threadIdx.x==0)cached_meta[0]=0;
  __syncthreads();
 }
 int* current_keys=LIBERO_POST_ONCE_KEYS?cached_body:nullptr;
 if(radix){
  if(LIBERO_POST_RADIX_BITS>1)
   post_contact_index_multibit(n,cc,b,adr,g1,g2,gb,index,offsets,counts,ping,pong,current_keys);
  else post_contact_index_radix(n,cc,b,adr,g1,g2,gb,index,offsets,counts,ping,pong,current_keys);
 }
 else post_contact_index_scan(n,cc,b,adr,g1,g2,gb,index,offsets,counts);
 if(cache){
  if(!(radix&&current_keys))for(int event=threadIdx.x;event<2*n;event+=blockDim.x)
   cached_body[event]=post_event_body(event,b,adr,g1,g2,gb);
  __syncthreads();
  if(threadIdx.x==0){cached_meta[1]=n;cached_meta[0]=1;}
 }else if(cached_meta&&threadIdx.x==0){
  // A bypass rebuild replaces CSR, so a later re-enabled cache must miss.
  cached_meta[0]=0;
 }
 __syncthreads();
}
} // namespace libero_post


#undef LIBERO_POST_RADIX_BITS
#define LIBERO_POST_RADIX_BITS 1
#undef LIBERO_POST_ONCE_KEYS
#define LIBERO_POST_ONCE_KEYS 0
namespace libero_post {
// All threads see the same scalar work domain. Cold host qualification also
// binds nv/ec/ns/ng and standalone CTA64 before this opt-in function exists.
__device__ __forceinline__ bool post_index_qualified_domain(int n,int cc,int b,
 int mode,int threshold,int cache){
 return blockDim.x==64&&mode==2&&threshold==256&&(cache==0||cache==1)&&
   ((b==38&&cc==529&&(n==512||n==516))||
    ((b==65||b==66)&&cc==1049&&(n==1032||n==1036)));
}
__device__ inline void post_contact_index(int n,int cc,int b,const int* adr,
 const int* g1,const int* g2,const int* gb,int* index,int* offsets,int* counts,
 int* ping,int* pong,int mode,int threshold,int* cached_body=nullptr,
 int* cached_meta=nullptr,int topology_cache=0){
 if(!post_index_qualified_domain(n,cc,b,mode,threshold,topology_cache)){
  libero_post_index_old::post_contact_index(n,cc,b,adr,g1,g2,gb,index,offsets,counts,
    ping,pong,mode,threshold,cached_body,cached_meta,topology_cache);
 }else if(topology_cache==0){
  // No cache-hit domain exists. Keys are per-original-event scratch and are
  // never considered a persistent topology identity or finite certificate.
  libero_post_index_miss::post_contact_index(n,cc,b,adr,g1,g2,gb,index,offsets,counts,
    ping,pong,mode,threshold,cached_body,cached_meta,0);
 }else{
  // Measured P04 2-bit implementation; deliberately excludes ONCE_KEYS from
  // any profile that can hit. The original exact hit comparison is retained.
  libero_post_index_2bit::post_contact_index(n,cc,b,adr,g1,g2,gb,index,offsets,counts,
    ping,pong,mode,threshold,cached_body,cached_meta,1);
 }
}
}
